package main

import (
	"fmt"
	"math"
)

func main() {

	var n, e int
	n = 0
	e = 0

	fmt.Printf(" %v", math.Pi)
	fmt.Scan(&n, &e)

	//lista (Slice) de n pessoas, a qual o [0] é a pessoa 1 e [n-1] é a pessoa 10
	listaDePessoas := make([]bool, n)

	for i := 0; i < n; i++ {
		listaDePessoas[i] = false
	}

	/*for i := 0; i < n; i++ {
		listaDePessoas[i] = i+1
	}*/

	posicaoDoPortadorDaEspada := e - 1

	//*TRUE quer dizer que a posição está com a espada
	listaDePessoas[posicaoDoPortadorDaEspada] = true

	for i := 0; i < n; i++ {

		fmt.Println("[")

		if posicaoDoPortadorDaEspada == i {
			listaDePessoas[i] = false

			//* mata/some o elemento da próxima pos
			listaDePessoas = append(listaDePessoas[:i+1], listaDePessoas[i+2:]...)

			listaDePessoas[i+1] = true
		}
		fmt.Println(listaDePessoas)
		fmt.Println("]")
	}

}
